import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {

  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;  

  console.log(billingItemCode)

  if (!billingItemCode) {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: "parameter_billingItem_code for rule Alumbrado publico-Precio por rangos de consumo not found"
      }
    }
  }

  const parameterBillingItemCodeForAmount = input?.parametros_de_la_regla?.parameter_billingItem_code_for_amount;
  const activeEnergyBillingItems = input.tsl_wo_work_order_attribute.billing_items.active_energy_billing_items;
  const consumo = activeEnergyBillingItems.find(item => item.legacy_billing_item_id === parameterBillingItemCodeForAmount);

  const percentagePricing = parseFloat(input.percentage_pricing.percentage_rate); 

  let totalAmount = (percentagePricing/100) * consumo.billing_item_amount;


 if (totalAmount != null) {
    const billingItems = input.tsl_wo_work_order_attribute.billing_items.public_lighting_billing_items;
    const billingItem = billingItems.find(item => item.legacy_billing_item_id === billingItemCode);
    billingItem.billing_item_amount = totalAmount;

    return {
      ...input,
      result: {
          total_amount: totalAmount,
          status: "OK",
          status_description: "Alumbrado publico-Porcentaje fijo calculation rule completed"
        }
    };
  } else {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: "The amount of the Alumbrado publico-Porcentaje fijo rule could not be calculated."
      }
    };
  }
};
